SET @prov_c := '%s';
SET @id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET	@start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

CREATE TABLE IF NOT EXISTS s_kpi_dental14(
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
	target int(9) DEFAULT 0,
	result int(9) DEFAULT 0,
	PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_kpi_dental14 WHERE id=@id AND b_year=(@b_year+543);

INSERT IGNORE INTO s_kpi_dental14
(
SELECT
  @id,pr.hospcode	,concat(h.provcode,SUBSTR(CONCAT('00',h.distcode),-2),SUBSTR(CONCAT('00',h.subdistcode),-2),SUBSTR(CONCAT('00',h.mu),-2)) as areacode
	,@send,DATE_FORMAT(now(),'%Y%m%d%H%i%s') as d_com,@b_year+543 as b_year
	,COUNT(DISTINCT IF(i.main_group NOT IN('ไม่จัดกลุ่ม'),concat(pr.hospcode,'-',pr.pid,'-',pr.seq,'-',pr.procedcode),null)) target
	,COUNT(DISTINCT IF(i.main_group IN('ทันตกรรมเฉพาะทาง'),concat(pr.hospcode,'-',pr.pid,'-',pr.seq,'-',pr.procedcode),null)) result
FROM 
		tmp_procedure_opd pr 
		INNER JOIN cwh_dent_icd10tm i ON  pr.PROCEDCODE = i.icd10tm
		INNER JOIN chospital h ON h.hoscode=pr.hospcode
WHERE h.provcode in(@prov_c) AND pr.DATE_SERV BETWEEN @start_d AND @end_d 
GROUP BY pr.hospcode
);
